export const listLogsInfiniteQueryKey = (
  options?: Options<ListLogsData>,
): QueryKey<Options<ListLogsData>> => createQueryKey('listLogs', options, true);

/**
 * List Logs
 *
 * List log rows, newest first.
 *
 * ``event_prefix`` accepts a comma-separated list of prefixes and keeps rows whose
 * event starts with any of them (e.g. ``warming_,spam_status``). Omitting it, or passing
 * the empty string, applies no filter; a value that yields no usable prefix (``" "``,
 * ``","``) is still a filter and matches nothing.
 */
export const listLogsInfiniteOptions = (options?: Options<ListLogsData>) => {
  const opts = infiniteQueryOptions<
    ListLogsResponse,
    ListLogsError,
    InfiniteData<ListLogsResponse>,
    QueryKey<Options<ListLogsData>>,
    string | null | Pick<QueryKey<Options<ListLogsData>>[0], 'body' | 'headers' | 'path' | 'query'>
  >(
    // @ts-ignore
    {
      queryFn: async ({ pageParam, queryKey, signal }) => {
        // @ts-ignore
        const page: Pick<
          QueryKey<Options<ListLogsData>>[0],
          'body' | 'headers' | 'path' | 'query'
        > =
          typeof pageParam === 'object'
            ? pageParam
            : {
                query: {
                  cursor: pageParam,
                },
              };
        const params = createInfiniteParams(queryKey, page);
        const { data } = await listLogs({
          ...options,
          ...params,
          signal,
          throwOnError: true,
        });
        return data;
      },
      queryKey: listLogsInfiniteQueryKey(options),
    },
  );
  return opts as Omit<typeof opts, 'initialData'>;
};

